--
-- Name: fn_activar_lotes(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_activar_lotes(p_product_id uuid) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_modo text;
BEGIN
    SELECT tracking_mode INTO v_modo FROM public.products WHERE id = p_product_id;

    IF v_modo IS NULL THEN
        RAISE EXCEPTION 'No existe el producto %.', p_product_id;
    END IF;

    IF v_modo = 'serial' THEN
        RAISE EXCEPTION 'El producto ya usa números de serie; no se puede pasar a lotes.';
    END IF;

    UPDATE public.products SET tracking_mode = 'lot', modified = now()
     WHERE id = p_product_id AND tracking_mode <> 'lot';
END $$;


ALTER FUNCTION public.fn_activar_lotes(p_product_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION fn_activar_lotes(p_product_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_activar_lotes(p_product_id uuid) IS 'Pasa un producto a seguimiento por lotes. El stock que ya tenía queda como existencia sin lote, y FEFO la consume primero por ser la más antigua.';


--
-- Name: fn_activar_series(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_activar_series(p_product_id uuid) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_modo text;
BEGIN
    SELECT tracking_mode INTO v_modo FROM public.products WHERE id = p_product_id;

    IF v_modo IS NULL THEN
        RAISE EXCEPTION 'No existe el producto %.', p_product_id;
    END IF;

    -- Simétrico a fn_activar_lotes, que rechaza pasar de 'serial' a 'lot'. Las
    -- existencias de lote agrupan varias unidades bajo un código; repartirlas en
    -- una fila por unidad exigiría inventar números de serie que nadie anotó.
    IF v_modo = 'lot' THEN
        RAISE EXCEPTION 'El producto ya usa lotes; no se puede pasar a números de serie.';
    END IF;

    UPDATE public.products SET tracking_mode = 'serial', modified = now()
     WHERE id = p_product_id AND tracking_mode <> 'serial';
END $$;


