--
-- Name: fn_mover_stock(uuid, numeric, integer, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_mover_stock(p_product_id uuid, p_delta numeric, p_user_id integer DEFAULT 0, p_stock_item_id uuid DEFAULT NULL::uuid) RETURNS TABLE(stock_item_id uuid, stock_before numeric, stock_after numeric)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_item    uuid;
    v_antes   numeric;
    v_despues numeric;
BEGIN
    IF p_stock_item_id IS NOT NULL THEN
        v_item := p_stock_item_id;
    ELSE
        -- Sin existencia indicada se usa la implícita, que es la única que tiene
        -- un producto en modo 'none'. Cuando se active 'lot', quien venda deberá
        -- elegir el lote (por FEFO) y pasarlo explícitamente.
        SELECT si.id INTO v_item
          FROM public.stock_items si
         WHERE si.product_id = p_product_id
           AND si.lot_code IS NULL
           AND si.serial_number IS NULL
           AND si.state
         LIMIT 1;

        IF v_item IS NULL THEN
            RAISE EXCEPTION 'El producto % no tiene una existencia sin lote. Si usa lotes, '
                            'hay que indicar cuál mover.', p_product_id;
        END IF;
    END IF;

    UPDATE public.stock_items si
       SET quantity    = si.quantity + p_delta,
           modified_by = p_user_id,
           modified    = now()
     WHERE si.id = v_item
    RETURNING si.quantity - p_delta, si.quantity INTO v_antes, v_despues;

    IF v_antes IS NULL THEN
        RAISE EXCEPTION 'No se encontró la existencia %.', v_item;
    END IF;

    -- La caché se mantiene acá, no en el backend. Es lo que garantiza que
    -- v_stock_descuadrado siga vacía.
    UPDATE public.products p
       SET current_stock = COALESCE(p.current_stock, 0) + p_delta,
           modified_by   = p_user_id,
           modified      = now()
     WHERE p.id = p_product_id;

    RETURN QUERY SELECT v_item, v_antes, v_despues;
END $$;


ALTER FUNCTION public.fn_mover_stock(p_product_id uuid, p_delta numeric, p_user_id integer, p_stock_item_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION fn_mover_stock(p_product_id uuid, p_delta numeric, p_user_id integer, p_stock_item_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_mover_stock(p_product_id uuid, p_delta numeric, p_user_id integer, p_stock_item_id uuid) IS 'Único camino para mover stock. Actualiza la existencia y la caché de products en una sola operación, y devuelve la existencia afectada con su saldo antes y después, para registrar el movimiento.';


--
-- Name: fn_recalcular_stock_producto(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_recalcular_stock_producto(p_product_id uuid) RETURNS numeric
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_total numeric;
BEGIN
    SELECT COALESCE(sum(quantity), 0) INTO v_total
      FROM public.stock_items
     WHERE product_id = p_product_id AND state;

    UPDATE public.products
       SET current_stock = v_total, modified = now()
     WHERE id = p_product_id;

    RETURN v_total;
END $$;


