-- Name: FUNCTION fn_recibir_lote(p_product_id uuid, p_cantidad numeric, p_lot_code character varying, p_expiry_date date, p_user_id integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_recibir_lote(p_product_id uuid, p_cantidad numeric, p_lot_code character varying, p_expiry_date date, p_user_id integer) IS 'Da entrada a un lote. Si ya existe esa combinación de lote y vencimiento, suma sobre la misma existencia en vez de duplicarla.';


--
-- Name: fn_recibir_serie(uuid, character varying, date, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_recibir_serie(p_product_id uuid, p_serial_number character varying, p_expiry_date date DEFAULT NULL::date, p_user_id integer DEFAULT 0) RETURNS TABLE(stock_item_id uuid, stock_before numeric, stock_after numeric)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_item   uuid;
    v_tenant integer;
    v_serie  varchar;
BEGIN
    v_serie := trim(p_serial_number);

    IF coalesce(v_serie, '') = '' THEN
        RAISE EXCEPTION 'El número de serie es obligatorio para un producto con seguimiento por series.';
    END IF;

    -- El tenant sale del producto, no de la sesión: mismo motivo que en
    -- fn_recibir_lote.
    SELECT p.tenant_id INTO v_tenant FROM public.products p WHERE p.id = p_product_id;

    IF v_tenant IS NULL THEN
        RAISE EXCEPTION 'No existe el producto %.', p_product_id;
    END IF;

    -- El índice único lo impediría igual, pero su mensaje no le dice nada a
    -- quien está recibiendo mercadería con el lector en la mano.
    SELECT si.id INTO v_item
      FROM public.stock_items si
     WHERE si.serial_number = v_serie;

    IF v_item IS NOT NULL THEN
        RAISE EXCEPTION 'El número de serie % ya está registrado.', v_serie;
    END IF;


        (tenant_id, product_id, serial_number, expiry_date, quantity, created_by, modified_by)
    VALUES (v_tenant, p_product_id, v_serie, p_expiry_date, 0, p_user_id, p_user_id)
    RETURNING id INTO v_item;

    RETURN QUERY SELECT * FROM public.fn_mover_stock(p_product_id, 1, p_user_id, v_item);
END $$;


ALTER FUNCTION public.fn_recibir_serie(p_product_id uuid, p_serial_number character varying, p_expiry_date date, p_user_id integer) OWNER TO postgres;

--
-- Name: FUNCTION fn_recibir_serie(p_product_id uuid, p_serial_number character varying, p_expiry_date date, p_user_id integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_recibir_serie(p_product_id uuid, p_serial_number character varying, p_expiry_date date, p_user_id integer) IS 'Da entrada a UNA unidad identificada por su número de serie. Rechaza un número repetido: sería la misma unidad física dos veces.';


--
-- Name: set_sequences_key(character varying); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.set_sequences_key(tablename character varying) RETURNS integer
    LANGUAGE plpgsql
    AS $$

declare 

	contador integer;

begin



	UPDATE sequences_key 

	SET    sequence_id  = sequence_id + 1 

	WHERE   table_name = tablename;



	SELECT into contador sequence_id 

	FROM   sequences_key 

	WHERE   table_name = tablename ;



	return contador;

end;

$$;


ALTER FUNCTION public.set_sequences_key(tablename character varying) OWNER TO postgres;

--
-- Name: fn_auth_lookup(character varying, integer); Type: FUNCTION; Schema: sec; Owner: postgres
--

CREATE FUNCTION sec.fn_auth_lookup(p_email character varying DEFAULT NULL::character varying, p_user_id integer DEFAULT NULL::integer) RETURNS TABLE(user_id integer, tenant_id integer, user_name character varying, change_password boolean, is_active boolean, email character varying, full_name character varying, uuid uuid, password character varying, mfa_enabled boolean, mfa_required boolean, rol_id integer, rol_name character varying, roles character varying)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'sec', 'public', 'pg_temp'
    AS $$
DECLARE
    v_tenant integer;
BEGIN
    RETURN QUERY
    SELECT u.id, u.tenant_id, u.user_name, u.change_password, u.is_active,
           u.email, u.full_name, u.uuid, u.password,
           COALESCE(m.is_enabled,  false),
           COALESCE(m.is_required, false),
           COALESCE(pr.rol_id,   0),
           COALESCE(pr.rol_name, '')::varchar,
           COALESCE(pr.roles,    '')::varchar
    FROM sec.users u
    -- JOIN, no LEFT JOIN: si la farmacia está desactivada, sus usuarios no entran.
    JOIN sec.tenants       t ON t.id = u.tenant_id AND t.is_active
    LEFT JOIN sec.user_mfa m ON m.user_id = u.id AND m.mfa_type = 'totp'
    LEFT JOIN LATERAL (
        SELECT
            -- Rol efectivo: los que no son 'Cajero' ordenan primero, y entre
            -- iguales decide el id. Determinista entre ejecuciones.
            (array_agg(r.id       ORDER BY (r.name_rol = 'Cajero'), r.id))[1] AS rol_id,
            (array_agg(r.name_rol ORDER BY (r.name_rol = 'Cajero'), r.id))[1] AS rol_name,
            string_agg(r.name_rol, ',' ORDER BY r.name_rol)                   AS roles
        FROM sec.users_roles ur
        JOIN sec.roles r ON r.id = ur.rol_id AND r.state
        WHERE ur.user_id = u.id AND ur.state
    ) pr ON true
    WHERE u.is_active
      AND ((p_email   IS NOT NULL AND u.email = p_email)
        OR (p_user_id IS NOT NULL AND u.id    = p_user_id));

    -- Encontrado el usuario, ya se sabe el tenant. Fijarlo acá hace que todo lo
    -- que siga en ESTA conexión corra con el tenant correcto y bajo RLS.
    SELECT u.tenant_id INTO v_tenant
    FROM sec.users u
    JOIN sec.tenants t ON t.id = u.tenant_id AND t.is_active
    WHERE u.is_active
      AND ((p_email   IS NOT NULL AND u.email = p_email)
        OR (p_user_id IS NOT NULL AND u.id    = p_user_id))
    LIMIT 1;

    IF v_tenant IS NOT NULL THEN
        PERFORM set_config('app.tenant_id', v_tenant::text, false);
    END IF;
END $$;


ALTER FUNCTION sec.fn_auth_lookup(p_email character varying, p_user_id integer) OWNER TO postgres;

--
-- Name: fn_provision_tenant(character varying, character varying, character varying, character varying, character varying); Type: FUNCTION; Schema: sec; Owner: postgres
--

CREATE FUNCTION sec.fn_provision_tenant(p_name character varying, p_slug character varying, p_admin_email character varying, p_admin_full_name character varying, p_admin_password character varying) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'sec', 'public', 'pg_temp'
    AS $$
DECLARE
    v_tenant integer;
    v_rol    integer;
    v_user   integer;
BEGIN
    -- -------------------------------------------------------------------------
    -- Validaciones
    -- -------------------------------------------------------------------------
    IF coalesce(trim(p_name), '') = '' THEN
        RAISE EXCEPTION 'El nombre de la farmacia es obligatorio.';
    END IF;

    IF coalesce(trim(p_slug), '') = '' THEN
        RAISE EXCEPTION 'El slug es obligatorio.';
    END IF;

    IF EXISTS (SELECT 1 FROM sec.tenants t WHERE lower(t.slug) = lower(p_slug)) THEN
        RAISE EXCEPTION 'Ya existe una farmacia con el identificador "%".', p_slug;
    END IF;

    -- email y user_name son únicos GLOBALMENTE, no por tenant: el login no lleva
    -- selector de farmacia, así que el correo es lo que resuelve a cuál pertenece
    -- quien entra. Un correo repetido entre farmacias haría el login ambiguo.
    IF EXISTS (SELECT 1 FROM sec.users u WHERE lower(u.email) = lower(p_admin_email)) THEN
        RAISE EXCEPTION 'El correo "%" ya está registrado en otra farmacia.', p_admin_email;
    END IF;

    -- -------------------------------------------------------------------------
    -- 1. La farmacia
    -- -------------------------------------------------------------------------

    VALUES (trim(p_name), lower(trim(p_slug)), true)
    RETURNING id INTO v_tenant;

    -- -------------------------------------------------------------------------
    -- 2. Datos maestros mínimos
    -- -------------------------------------------------------------------------
    PERFORM sec.fn_seed_tenant_master_data(v_tenant);

    -- -------------------------------------------------------------------------
    -- 3. Rol administrador de la farmacia
    -- -------------------------------------------------------------------------
    -- Los roles son por tenant; los formularios son globales. Por eso se crea un
    -- rol nuevo y se le asignan los formularios existentes, sin duplicarlos.
    v_rol := set_sequences_key('sec.roles');


        (id, name_rol, description, state, created_by, created, modified_by, modified, tenant_id)
    VALUES (v_rol, 'SuperAdmin', 'Administrador de la farmacia',
            true, 1, now(), 1, now(), v_tenant);


        (rol_id, form_id, can_create, can_read, can_update, can_delete,
         state, created_by, created, modified_by, modified, tenant_id)
    SELECT v_rol, f.id, true, true, true, true, true, 1, now(), 1, now(), v_tenant
      FROM sec.forms f
     WHERE f.state;

    -- -------------------------------------------------------------------------
    -- 4. Usuario administrador
    -- -------------------------------------------------------------------------
    v_user := set_sequences_key('sec.users');


        (id, user_name, password, email, full_name, last_access, change_password,
         is_active, created_by, created, modified_by, modified, uuid, tenant_id)
    VALUES (v_user, lower(trim(p_admin_email)), p_admin_password, lower(trim(p_admin_email)),
            p_admin_full_name, now(),
            true,   -- obliga a cambiar la contraseña en el primer ingreso
            true, v_user, now(), v_user, now(), gen_random_uuid(), v_tenant);


        (user_id, rol_id, state, created_by, created, modified_by, modified, tenant_id)
    VALUES (v_user, v_rol, true, v_user, now(), v_user, now(), v_tenant);

    RETURN v_tenant;
END $$;


ALTER FUNCTION sec.fn_provision_tenant(p_name character varying, p_slug character varying, p_admin_email character varying, p_admin_full_name character varying, p_admin_password character varying) OWNER TO postgres;

--
-- Name: FUNCTION fn_provision_tenant(p_name character varying, p_slug character varying, p_admin_email character varying, p_admin_full_name character varying, p_admin_password character varying); Type: COMMENT; Schema: sec; Owner: postgres
--

COMMENT ON FUNCTION sec.fn_provision_tenant(p_name character varying, p_slug character varying, p_admin_email character varying, p_admin_full_name character varying, p_admin_password character varying) IS 'Da de alta una farmacia con sus datos maestros mínimos, su rol SuperAdmin y su usuario administrador. SECURITY DEFINER porque provisionar cruza tenants. Devuelve el id del tenant creado.';


--
-- Name: fn_seed_tenant_master_data(integer); Type: FUNCTION; Schema: sec; Owner: postgres
--

CREATE FUNCTION sec.fn_seed_tenant_master_data(p_tenant integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'sec', 'public', 'pg_temp'
    AS $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM sec.tenants WHERE id = p_tenant) THEN
        RAISE EXCEPTION 'No existe la farmacia %.', p_tenant;
    END IF;

    IF NOT EXISTS (SELECT 1 FROM public.unit_of_measurement WHERE tenant_id = p_tenant) THEN
             is_default, is_active, state, created_by, created, modified_by, modified, tenant_id)
        VALUES (gen_random_uuid(), 'UNIDAD', 100, 1, false, true, true, true,
                1, now(), 1, now(), p_tenant);
    END IF;

    IF NOT EXISTS (SELECT 1 FROM public.laboratories WHERE tenant_id = p_tenant) THEN
             is_active, state, created_by, created, modified_by, modified, tenant_id)
        VALUES (gen_random_uuid(), 'SIN LABORATORIO', 'Valor por defecto, editable', '', '',
                true, true, 1, now(), 1, now(), p_tenant);
    END IF;

    IF NOT EXISTS (SELECT 1 FROM public.categories WHERE tenant_id = p_tenant) THEN
             created_by, created, modified_by, modified, tenant_id)
        VALUES (gen_random_uuid(), 'GENERAL', 'Categoría por defecto, editable',
                true, true, 1, now(), 1, now(), p_tenant);
    END IF;

    IF NOT EXISTS (SELECT 1 FROM public.payment_methods WHERE tenant_id = p_tenant) THEN
    END IF;

    IF NOT EXISTS (SELECT 1 FROM public.customers WHERE tenant_id = p_tenant AND is_generic) THEN
             state, created_by, created, modified_by, modified, tenant_id)
        VALUES (gen_random_uuid(), 'Cliente Genérico', '0', '', '', true, true,
                true, 1, now(), 1, now(), p_tenant);
    END IF;
END $$;


ALTER FUNCTION sec.fn_seed_tenant_master_data(p_tenant integer) OWNER TO postgres;

--
-- Name: set_llave_primaria(character varying); Type: FUNCTION; Schema: siat; Owner: postgres
--

CREATE FUNCTION siat.set_llave_primaria(nombretabla character varying) RETURNS integer
    LANGUAGE plpgsql
    AS $$

declare 

	contador integer;

begin

	UPDATE siat.llaves_primarias 

	SET    secuencia = secuencia + 1 

	WHERE   nombre_tabla = nombretabla;



	SELECT into contador secuencia 

	FROM   siat.llaves_primarias 

	WHERE   nombre_tabla = nombretabla; 



	return contador;

end;

$$;


ALTER FUNCTION siat.set_llave_primaria(nombretabla character varying) OWNER TO postgres;

--
-- Name: set_secuencia_factura(integer); Type: FUNCTION; Schema: siat; Owner: postgres
--

CREATE FUNCTION siat.set_secuencia_factura(gestion_par integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$

declare 

	contador integer;

begin

	UPDATE siat.secuencia_facturas 

	SET    secuencia = secuencia + 1 

	WHERE  gestion= gestion_par;



	SELECT into contador secuencia 

	FROM   siat.secuencia_facturas 

	WHERE  gestion= gestion_par; 



	return contador;

end;

$$;


ALTER FUNCTION siat.set_secuencia_factura(gestion_par integer) OWNER TO postgres;

