--
-- Name: v_mermas; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.v_mermas WITH (security_invoker='true') AS
 SELECT sm.tenant_id,
    sm.product_id,
    p.product_code,
    p.product_name,
    si.lot_code,
    si.expiry_date,
    abs(sm.quantity) AS cantidad,
    ((abs(sm.quantity))::numeric * p.sale_price) AS valor_perdido,
    sm.reason,
    sm.observation,
    sm.created,
    sm.created_by
   FROM ((public.stock_movements sm
     JOIN public.products p ON ((p.id = sm.product_id)))
     LEFT JOIN public.stock_items si ON ((si.id = sm.stock_item_id)))
  WHERE (((sm.movement_type)::text = 'MERMA'::text) AND sm.state);


ALTER VIEW public.v_mermas OWNER TO postgres;

--
-- Name: v_stock_descuadrado; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.v_stock_descuadrado WITH (security_invoker='true') AS
 SELECT p.tenant_id,
    p.id AS product_id,
    p.product_name,
    p.current_stock AS cache,
    COALESCE(sum(si.quantity), (0)::numeric) AS "real",
    (p.current_stock - COALESCE(sum(si.quantity), (0)::numeric)) AS diferencia
   FROM (public.products p
     LEFT JOIN public.stock_items si ON (((si.product_id = p.id) AND si.state)))
  GROUP BY p.tenant_id, p.id, p.product_name, p.current_stock
 HAVING (p.current_stock IS DISTINCT FROM COALESCE(sum(si.quantity), (0)::numeric));


ALTER VIEW public.v_stock_descuadrado OWNER TO postgres;

--
-- Name: VIEW v_stock_descuadrado; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON VIEW public.v_stock_descuadrado IS 'Productos donde products.current_stock no coincide con la suma de sus existencias. Debe estar vacía; si no, algo escribió el stock sin pasar por el libro mayor.';


--
-- Name: v_stock_por_vencer; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.v_stock_por_vencer WITH (security_invoker='true') AS
 SELECT si.tenant_id,
    si.id AS stock_item_id,
    p.id AS product_id,
    p.product_code,
    p.product_name,
    si.lot_code,
    si.expiry_date,
    si.quantity,
    (si.expiry_date - CURRENT_DATE) AS dias_restantes,
        CASE
            WHEN (si.expiry_date < CURRENT_DATE) THEN 'VENCIDO'::text
            WHEN (si.expiry_date <= (CURRENT_DATE + 30)) THEN 'CRITICO'::text
            WHEN (si.expiry_date <= (CURRENT_DATE + 90)) THEN 'PROXIMO'::text
            ELSE 'VIGENTE'::text
        END AS estado,
    (si.quantity * p.sale_price) AS valor_en_riesgo
   FROM (public.stock_items si
     JOIN public.products p ON ((p.id = si.product_id)))
  WHERE (si.state AND (si.quantity > (0)::numeric) AND (si.expiry_date IS NOT NULL));


ALTER VIEW public.v_stock_por_vencer OWNER TO postgres;

--
-- Name: VIEW v_stock_por_vencer; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON VIEW public.v_stock_por_vencer IS 'Existencias con vencimiento, clasificadas por urgencia. valor_en_riesgo es a precio de venta: es lo que se pierde si no se rota a tiempo.';


--
-- Name: v_trazabilidad_lote; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.v_trazabilidad_lote WITH (security_invoker='true') AS
 SELECT si.tenant_id,
    si.lot_code,
    si.expiry_date,
    p.product_code,
    p.product_name,
    s.id AS sale_id,
    s.sale_date,
    c.full_name AS cliente,
    c.document_number,
    c.cellphone,
    sd.quantity
   FROM ((((public.stock_items si
     JOIN public.products p ON ((p.id = si.product_id)))
     JOIN public.sales_detail sd ON ((sd.stock_item_id = si.id)))
     JOIN public.sales s ON ((s.id = sd.sale_id)))
     JOIN public.customers c ON ((c.id = s.customer_id)))
  WHERE ((si.lot_code IS NOT NULL) AND sd.state AND s.state);


ALTER VIEW public.v_trazabilidad_lote OWNER TO postgres;

--
-- Name: VIEW v_trazabilidad_lote; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON VIEW public.v_trazabilidad_lote IS 'A quién se le vendió cada lote. Es lo que permite responder a un retiro de mercado del laboratorio.';


--
-- Name: v_trazabilidad_serie; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.v_trazabilidad_serie WITH (security_invoker='true') AS
 SELECT si.tenant_id,
    si.serial_number,
    si.expiry_date,
    p.product_code,
    p.product_name,
    s.id AS sale_id,
    s.sale_date,
    c.full_name AS cliente,
    c.document_number,
    c.cellphone
   FROM ((((public.stock_items si
     JOIN public.products p ON ((p.id = si.product_id)))
     JOIN public.sales_detail sd ON ((sd.stock_item_id = si.id)))
     JOIN public.sales s ON ((s.id = sd.sale_id)))
     JOIN public.customers c ON ((c.id = s.customer_id)))
  WHERE ((si.serial_number IS NOT NULL) AND sd.state AND s.state);


ALTER VIEW public.v_trazabilidad_serie OWNER TO postgres;

--
-- Name: VIEW v_trazabilidad_serie; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON VIEW public.v_trazabilidad_serie IS 'A quién se le entregó cada número de serie. Es la consulta de una garantía.';


